/// Used to select a data source location.
/// C# `enum SourceSelectionOption : i32`.
#[repr(i32)]
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
pub enum SourceSelectionOption {
    None = 0x0,
    Github = 0x1,
    LocalDisk = 0x2,
}

impl SourceSelectionOption {
    /// Decode from the on-disk value. `None` for anything undefined —
    /// a C-style cast would produce a value outside the enum, which is UB.
    pub fn fromRaw(v: i32) -> Option<Self> {
        Some(match v {
            0x0 => Self::None,
            0x1 => Self::Github,
            0x2 => Self::LocalDisk,
            _ => return None,
        })
    }
    /// The on-disk value.
    pub fn toRaw(self) -> i32 {
        self as i32
    }
}

