bitflags::bitflags! {
    /// C# `[Flags] enum SpellFlags : i32`.
    #[derive(Debug, Clone, Copy, PartialEq, Eq, Hash, Default)]
    pub struct SpellFlags: i32 {
        const Resistable = 0x1;
        const PKSensitive = 0x2;
        const Beneficial = 0x4;
        const SelfTargeted = 0x8;
        const Reversed = 0x10;
        const NotIndoor = 0x20;
        const NotOutdoor = 0x40;
        const NotResearchable = 0x80;
        const Projectile = 0x100;
        const CreatureSpell = 0x200;
        const ExcludedFromItemDescriptions = 0x400;
        const IgnoresManaConversion = 0x800;
        const NonTrackingProjectile = 0x1000;
        const FellowshipSpell = 0x2000;
        const FastCast = 0x4000;
        const IndoorLongRange = 0x8000;
        const DamageOverTime = 0x10000;
        const UNKNOWN = 0x20000;
    }
}

