/// C# `enum VendorType : i32`.
#[repr(i32)]
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
pub enum VendorType {
    Undef = 0x0,
    Open = 0x1,
    Close = 0x2,
    Sell = 0x3,
    Buy = 0x4,
    Heartbeat = 0x5,
}

impl VendorType {
    /// Decode from the on-disk value. `None` for anything undefined —
    /// a C-style cast would produce a value outside the enum, which is UB.
    pub fn fromRaw(v: i32) -> Option<Self> {
        Some(match v {
            0x0 => Self::Undef,
            0x1 => Self::Open,
            0x2 => Self::Close,
            0x3 => Self::Sell,
            0x4 => Self::Buy,
            0x5 => Self::Heartbeat,
            _ => return None,
        })
    }
    /// The on-disk value.
    pub fn toRaw(self) -> i32 {
        self as i32
    }
}

